onChange.script:
if currentValue is None or currentValue.value != 'Recurring':
	return

info = self.custom.info
if not info.rruleStr:
	#A new Recurring trigger starts as daily from the next whole hour, so it has a valid rule before the user edits it
	nextHour = system.date.addHours(system.date.setTime(system.date.now(), system.date.getHour24(system.date.now()), 0, 0), 1)
	self.custom.info.rruleStr = 'FREQ=DAILY;INTERVAL=1'
	self.custom.info.rruleStartDate = nextHour

self.custom.recurring = {'rruleStr': self.custom.info.rruleStr, 'startDate': self.custom.info.rruleStartDate, 'generateAheadDays': None, 'assetPath': None}
return

transforms.code:
if not value['rule']:
	return ''
check = system.kanoa.schedule.validateRrule(value['rule'])
if not check['valid']:
	return system.util.translate('Invalid rule', self.session.props.locale) + ': %s' % check['error']
#Expanded in the device's zone, as the Start Date reads; the scheduler expands in each asset's site zone (the same where they match)
deviceZone = self.session.props.device.timezone.id
dates = system.kanoa.schedule.rruleToDates(value['rule'], value['start'], system.date.now(), 5, deviceZone)
if not dates:
	return 'No upcoming occurrences'
#In the device's time zone, as the Start Date field shows it: this runs on the gateway, which would format in its own (868m4x3xw)
from java.text import SimpleDateFormat
from java.util import TimeZone
fmt = SimpleDateFormat(system.kanoa.date.localizeDateFormat('EEE MMM d, yyyy h:mm a', value['locale']))
if deviceZone: fmt.setTimeZone(TimeZone.getTimeZone(deviceZone))
return 'Next: ' + ', '.join([fmt.format(d) for d in dates])
